/*
 * A285413  Positions of 1 in A285411; complement of A285412.
 * https://oeis.org/A285413
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = position of the n-th 1 in A285411, the fixed point of
 *            0->010010, 1->1101011 (word generated by iterating the morphism)
 * Range:     u8 n <= 137, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 79 terms through n = 9088 (2026-11-08)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>

seq_t a(idx_t n)
{
    size_t need = (size_t)n;
    size_t len = 1;
    unsigned char *cur = (unsigned char *)malloc(1);
    if (!cur) return (seq_t)0;
    cur[0] = 0;

    for (;;) {
        size_t ones = 0;
        for (size_t i = 0; i < len; ++i) ones += cur[i];
        if (ones >= need) break;

        size_t newlen = 0;
        for (size_t i = 0; i < len; ++i) newlen += cur[i] ? 7 : 6;
        unsigned char *next = (unsigned char *)malloc(newlen);
        if (!next) { free(cur); return (seq_t)0; }

        static const unsigned char g0[6] = {0,1,0,0,1,0};
        static const unsigned char g1[7] = {1,1,0,1,0,1,1};
        size_t pos = 0;
        for (size_t i = 0; i < len; ++i) {
            if (cur[i]) {
                for (int k = 0; k < 7; ++k) next[pos++] = g1[k];
            } else {
                for (int k = 0; k < 6; ++k) next[pos++] = g0[k];
            }
        }
        free(cur);
        cur = next;
        len = newlen;
    }

    size_t cnt = 0;
    size_t result = 0;
    for (size_t i = 0; i < len; ++i) {
        if (cur[i]) {
            ++cnt;
            if (cnt == need) { result = i + 1; break; }
        }
    }
    free(cur);
    return (seq_t)result;
}
